### Executed helper command

```bash
node --input-type=module <<'NODE'
import { mkdirSync, writeFileSync } from 'node:fs';
import { registerHooks } from 'node:module';
import { fileURLToPath } from 'node:url';
const sourceRoot = '<benchmark-workspace>/snapshots/pack-cobalt';
const runDir = '<benchmark-workspace>/iteration-1/eval-3-dirty-preflight/candidate/run-2';
const loadedFiles = [];
const hook = registerHooks({
  load(url, context, nextLoad) {
    const result = nextLoad(url, context);
    if (url.startsWith('file:')) loadedFiles.push(fileURLToPath(url));
    return result;
  },
});
const { evaluateWorkingTree } = await import(`${sourceRoot}/_refs/orchestration/execution-contract.mjs`);
const inputs = {
  A: { unrelated_dirty_paths: ['src'], intended_output_paths: ['src/**'] },
  B: { unrelated_dirty_paths: ['notes.md'], intended_output_paths: ['src/category.mjs'] },
};
const results = Object.fromEntries(Object.entries(inputs).map(([unit, input]) => [unit, evaluateWorkingTree(input)]));
hook.deregister();
mkdirSync(`${runDir}/outputs`, { recursive: true });
writeFileSync(`${runDir}/outputs/helper-results.json`, `${JSON.stringify(results, null, 2)}\n`);
writeFileSync(`${runDir}/evaluation-record.json`, `${JSON.stringify({node_version:process.version,platform:process.platform,inputs,loaded_module_files:loadedFiles}, null, 2)}\n`);
console.log(JSON.stringify(results, null, 2));
console.log(JSON.stringify({ node_version: process.version, platform: process.platform, loaded_module_files: loadedFiles }, null, 2));
NODE
```

